{"file_path": "/home/zhaodan/work/NodeJsProjects/agent-hub-web/src/utils/redact.ts", "content": "/**
 * 敏感字段遮罩（前端展示层）。
 *
 * 后端 M5 已保证平台密钥接口与审计 detail 不回显明文/密文；这里再对
 * 审批 payload、审计 detail 中可能由用户/工具带入的敏感键做一层展示遮罩，
 * 默认折叠，用户可显式展开本地数据。
 */

const SENSITIVE_KEY_RE =
  /^(password|passwd|pwd|secret|secrets|token|access_token|refresh_token|id_token|api_key|apikey|api_secret|client_secret|authorization|proxy-authorization|cookie|set-cookie|private_key|credential|credentials|passphrase)$/i

const MASK = '••••'

export function isSensitiveKey(key: string): boolean {
  return SENSITIVE_KEY_RE.test(key.trim())
}

/** 递归遮罩对象/数组中的敏感键；不修改入参。 */
export function redactValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => redactValue(item))
  }
  if (value && typeof value === 'object') {
    const result: Record<string, unknown> = {}
    for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
      result[key] = isSensitiveKey(key) ? MASK : redactValue(item)
    }
    return result
  }
  return value
}

/** 是否包含敏感键（用于提示「已遮罩」）。 */
export function containsSensitiveKey(value: unknown): boolean {
  if (Array.isArray(value)) return value.some((item) => containsSensitiveKey(item))
  if (value && typeof value === 'object') {
    return Object.entries(value as Record<string, unknown>).some(
      ([key, item]) => isSensitiveKey(key) || containsSensitiveKey(item),
    )
  }
  return false
}
"}

