  width: 12px;
  height: 12px;
  color: var(--ink-3);
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 0.15s;
}

.chevron.is-open {
  transform: rotate(180deg);
}

.rj-note {
  color: var(--amber-text);
  font-size: 10.5px;
}

.rj-actions {
  display: flex;
  gap: 5px;
  margin-left: auto;
}

.rj-btn {
  height: 24px;
