现在替换 `resolveApproval` 函数为 `resolveApprovalById` + 兼容 `resolveApproval`，并处理错误码。

当前代码（571-603 行附近）：
```ts
async function resolveApproval(approve: boolean): Promise<void> {
  const approvalId = state.value.pendingApprovalId
  ...
}
```
替换为两个函数。

注意 `note` 参数可选；`approvalsApi.decide` body 支持 note。

编写：

```ts
async function resolveApprovalById(
  approvalId: string,
  approve: boolean,
  note = '',
): Promise<ApprovalOutcome> {
  const decision = approve ? 'approve' : 'reject'
  if (resolvingApproval.value) return { approvalId, decision, kind:'failed', message:'正在处理其他审批', resumed:false }
  // 若该 id 不在 pending 列表，仍允许调用（审批中心场景不会走这里）
  resolvingApproval.value = true
  resolvingApprovalId.value = approvalId
  try {
    const result = await approvalsApi.decide(approvalId, { decision, ...(note ? { note } : {}) })
    state.value = markApprovalResolved(state.value, approvalId, decision)
    if (result.resumed) {
      state.value = { ...state.value, streaming: true, runStatus:'running', finishReason:null, error:null, recovery:null }
      return { ...kind:'resumed', message:'已批准，运行将继续' / '已拒绝，运行将继续收尾' }
    }
    if (result.resume_error === '本轮还有其他审批待处理') {
      state.value = { ...state.value, streaming: true, runStatus:'interrupted', recovery:null }
      return {kind:'waiting_others', message:'审批已记录，本轮还有其他审批待处理'}
    }
    if (result.resume_error === '运行已结束' || result.resume_error === '运行不存在') {
      state.value = markAllApprovalsResolved({ ...state.value, streaming:false, recovery:null })
      await refreshHistory().catch(() => undefined)
      return {kind:'run_ended', message:'审批已记录，运行已结束'}
    }
    state.value = {
      ...state.value,
      streaming: false,
      recovery: {kind:'approval_resume_failed', code:'approval_resume_failed', message: result.resume_error ?? '审批已记录，但后端未能自动恢复运行', runId: result.run_id, runStatus: state.value.runStatus, retryable:false},
    }
    return {kind:'not_resumed', message: ...}
  } catch (error) {
    if (error instanceof ApiRequestError && error.code === 'approval_expired') {
      state.value = markApprovalExpired(state.value, approvalId)
      state.value = {...state.value, streaming:false, recovery:null}
      await refreshHistory().catch(()=>undefined)
      return {kind:'expired', message:'审批已过期，无法继续'}
    }
    if (error instanceof ApiRequestError && error.code === 'approval_already_decided') {
      await refreshHistory().catch(()=>undefined)
      return {kind:'already_decided', message:'审批已处理，请刷新状态'}
    }
    return {kind:'failed', message: errorMessage(error,'审批失败，请稍后重试')}
  } finally {
    resolvingApproval.value = false
    resolvingApprovalId.value = null
  }
}

async function resolveApproval(approve: boolean): Promise<ApprovalOutcome> {
  const id = state.value.pendingApprovalId ?? state.value.pendingApprovalIds[0] ?? null
  if (!id) return { approvalId:'', decision: approve ? 'approve':'reject', kind:'failed', message:'当前没有待处理审批', resumed:false }
  return resolveApprovalById(id, approve)
}
```

注意 `markAllApprovalsResolved({ ...state.value, streaming:false, recovery:null })` 会清 pending 并标 waiting→ok。好。

但 `refreshHistory` 在审批后 run 继续时会拉取历史，可能把状态消息更新；在 resumed=true 分支不要调用。

`ApprovalOutcome` 的 decision 类型在失败时也需要 decision，用局部变量。

替换函数。

