const decision = approve ? 'approve' : 'reject'
if (resolvingApproval.value) {
  return {
    approvalId,
    decision,
    kind: 'failed',
    message: '正在处理其他审批，请稍候',
    resumed: false,
  }
}

resolvingApproval.value = true
resolvingApprovalId.value = approvalId
try {
  const result = await approvalsApi.decide(approvalId, {
    decision,
    ...(note ? { note } : {}),
  })
  state.value = markApprovalResolved(state.value, approvalId, decision)

  if (result.resumed) {
    // 流可能已经先发出 message.done（尤其是 mock/快速路径）；终态优先，
    // 不要让迟到的决定响应把 finishReason 覆盖回 null。
    const terminal =
      state.value.runStatus === 'succeeded' ||
      state.value.runStatus === 'failed' ||
      state.value.runStatus === 'canceled'
    if (!terminal) {
      state.value = {
        ...state.value,
        streaming: true,
        runStatus: 'running',
        finishReason: null,
        error: null,
        recovery: null,
      }
    }
    return {
      approvalId,
      decision,
      kind: 'resumed',
      message: approve ? '已批准，运行将继续' : '已拒绝，运行将继续收尾',
      resumed: true,
    }
  }

  if (result.resume_error === '本轮还有其他审批待处理') {
    state.value = {
      ...state.value,
      streaming: true,
      runStatus: 'interrupted',
      recovery: null,
    }
    return {
      approvalId,
      decision,
      kind: 'waiting_others',
      message: '审批已记录，本轮还有其他审批待处理',
      resumed: false,
    }
  }

  if (result.resume_error === '运行已结束' || result.resume_error === '运行不存在') {
    state.value = markAllApprovalsResolved({
      ...state.value,
      streaming: false,
      recovery: null,
    })
    await refreshHistory().catch(() => undefined)
    return {
      approvalId,
      decision,
      kind: 'run_ended',
      message: '审批已记录，运行已结束',
      resumed: false,
    }
  }

  state.value = {
    ...state.value,
    streaming: false,
    recovery: {
      kind: 'approval_resume_failed',
      code: 'approval_resume_failed',
      message:
        result.resume_error ??
        '审批已记录，但当前后端未能自动恢复运行；可刷新状态或放弃本轮。',
      runId: result.run_id,
      runStatus: state.value.runStatus,
      retryable: false,
    },
  }
  await refreshHistory().catch(() => undefined)
  return {
    approvalId,
    decision,
    kind: 'not_resumed',
    message: result.resume_error ?? '审批已记录，但运行未自动恢复',
    resumed: false,
  }
} catch (error) {
  if (error instanceof ApiRequestError && error.code === 'approval_expired') {
    state.value = markApprovalExpired(state.value, approvalId)
    state.value = { ...state.value, streaming: false, recovery: null }
    await refreshHistory().catch(() => undefined)
    return {
      approvalId,
      decision,
      kind: 'expired',
      message: '审批已过期，无法继续执行',
      resumed: false,
    }
  }
  if (error instanceof ApiRequestError && error.code === 'approval_already_decided') {
    state.value = markApprovalResolved(state.value, approvalId, decision)
    await refreshHistory().catch(() => undefined)
    return {
      approvalId,
      decision,
      kind: 'already_decided',
      message: '审批已处理，请刷新状态',
      resumed: false,
    }
  }
  return {
    approvalId,
    decision,
    kind: 'failed',
    message: errorMessage(error, '审批失败，请稍后重试'),
    resumed: false,
  }

修改：
1. resumed 分支：若无活动 controller，`void adoptRun(result.run_id)`。判断 controller 变量（闭包）。
2. already_decided：detail + hydrate + clearPendingApproval（不写 decision）。

注意 `controller` 在审批等待时可能为 null（流关闭）或非 null（流保持）；如果非 null，流会收 run.resumed，无需 adoptRun。若 null，adoptRun 轮询。

实现：
```ts
if (!controller) void adoptRun(result.run_id)
```
但 adoptRun 内部 `clearPolling` + `runsApi.get` 会设置 streaming。好。

already_decided：
```ts
try {
  const approval = await approvalsApi.detail(approvalId)
  state.value = hydrateApprovals(state.value, [approval])
  if (approval.status !== 'pending') {
    state.value = clearPendingApproval(state.value, approvalId)
  }
} catch { /* detail 失败至少移除指针 */ state.value = clearPendingApproval(state.value, approvalId) }
await refreshHistory()
```
注意 `hydrateApprovals` 对已决定卡设置 decision 与服务端一致；pending 列表如果 status pending 仍加回（但 409 已决定不应 pending，可能竞态）。若 pending 则保留。

编辑。

