/**
 * 字符串级遮罩：后端 `payload_preview` 是原始 args 的 JSON 字符串，
 * 无法通过对象键递归处理；先尝试解析，失败时用正则替换敏感键的值。
 */
export function redactText(text: string): string {
  if (!text) return text
  try {
    return JSON.stringify(redactValue(JSON.parse(text) as unknown))
